DROP TABLE configuration;
CREATE TABLE configuration (
  `key` text NOT NULL,
  private tinyint(4) NOT NULL,
  value mediumtext NOT NULL
);

ALTER TABLE tracking MODIFY COLUMN type text;

UPDATE tracking
SET type = CASE type
  WHEN 'VACATION' THEN 'vacation'
  WHEN 'SELFCARE' THEN 'selfcare'
  WHEN 'TENURE' THEN 'tenure'
  WHEN 'OVERTIME' THEN 'overtime'
  WHEN 'PLANNED_WORK' THEN 'plannedWork'
END;

ALTER TABLE tracking
MODIFY COLUMN type ENUM('vacation', 'selfcare', 'tenure', 'overtime', 'plannedWork') NOT NULL;

